//! Test-only timing observations. Production lock budget/CAS/replay are untouched.
use super::*;
use std::{collections::BTreeMap,sync::{Arc,atomic::{AtomicBool,Ordering}},time::{Instant,Duration},io::Write};
fn id()->String{uuid::Uuid::new_v4().to_string()}
fn repository(root:PathBuf)->Repository{let mut r=Repository::new(root,Policy::import_qa());r.clock=Clock{fixed:Some(Arc::new(Mutex::new("2026-10-28T12:00:00Z".into())))};r}
#[test]fn assess_existing_cas_without_weakening_the_five_second_lock_budget(){
 let root=std::env::temp_dir().join("opencode").join(format!("5d3b4e-cas-{}",id()));fs::create_dir(&root).unwrap();fs::create_dir(root.join("fiscal")).unwrap();let source=Path::new(env!("CARGO_MANIFEST_DIR")).join("../docs/evidence/5d3b4b/legacy");for name in ["fiscal-initialization.json","fiscal-initialized.json","fiscal/repository.sqlite3"]{fs::copy(source.join(name),root.join(name)).unwrap();}
 let repo=repository(root.clone());repo.open_existing().unwrap();let(_,items)=repo.installation_metadata(10,"").unwrap();let iid=&items.iter().max_by_key(|i|i.revision).unwrap().installation_id;let admission=repo.prepare_activation(ActivationIntent::Admit,Some(iid),None,None).unwrap();repo.confirm_activation(&id(),&admission).unwrap();let select=repo.prepare_activation(ActivationIntent::Select,Some(iid),admission.admission_id.as_deref(),None).unwrap();fs::write(root.join("selection-request.json"),core::canonical::bytes(&select.action).unwrap()).unwrap();
 let(gate_wait_ms,os_lock_wait_ms,replay_ms,exclusive_replay_hold_ms)={let t=Instant::now();let _gate=repo.gate.lock().unwrap();let gate=t.elapsed().as_secs_f64()*1000.;let t=Instant::now();let lock=paths::lock(&repo.root).unwrap();let wait=t.elapsed().as_secs_f64()*1000.;let held=Instant::now();let(c,m)=repo.existing().unwrap();let t=Instant::now();replay::rebuild(&c,&repo.policy,&m).unwrap();let replay=t.elapsed().as_secs_f64()*1000.;drop(c);drop(lock);(gate,wait,replay,held.elapsed().as_secs_f64()*1000.)};
 let running=Arc::new(AtomicBool::new(true));let stop=running.clone();let observed=Arc::new(Mutex::new(Vec::<f64>::new()));let output=observed.clone();let path=root.join(".fiscal-maintenance.lock");let observer=std::thread::spawn(move||{let f=std::fs::OpenOptions::new().read(true).write(true).open(path).unwrap();let mut busy:Option<Instant>=None;while stop.load(Ordering::Relaxed){match f.try_lock(){Ok(())=>{let _=f.unlock();if let Some(t)=busy.take(){output.lock().unwrap().push(t.elapsed().as_secs_f64()*1000.);}},Err(std::fs::TryLockError::WouldBlock)=>{busy.get_or_insert_with(Instant::now);},Err(e)=>panic!("{e:?}")}std::thread::sleep(Duration::from_millis(5));}if let Some(t)=busy{output.lock().unwrap().push(t.elapsed().as_secs_f64()*1000.);}});
 let spawn=||std::process::Command::new(std::env::current_exe().unwrap()).args(["--exact","fiscal_repository::cas_assessment_tests::cas_child","--ignored","--nocapture"]).env("NOMINA_4E_CAS_ROOT",&root).stdout(std::process::Stdio::piped()).stderr(std::process::Stdio::piped()).spawn().unwrap();let a=spawn();let b=spawn();let a=a.wait_with_output().unwrap();let b=b.wait_with_output().unwrap();running.store(false,Ordering::Relaxed);observer.join().unwrap();assert!(a.status.success()&&b.status.success());let results=[a,b].iter().map(|c|String::from_utf8_lossy(&c.stdout).lines().find_map(|l|l.strip_prefix("CAS_4E_OBSERVATION:").map(|j|serde_json::from_str::<serde_json::Value>(j).unwrap())).unwrap()).collect::<Vec<_>>();assert_eq!(results.iter().filter(|v|v["outcome"]=="SELECTED").count(),1);assert!(results.iter().all(|v|["SELECTED","STALE_GENERATION","BUSY"].iter().any(|s|v["outcome"]==*s)));assert_eq!(repo.selection_status().unwrap().selection.generation,1);
 let profile=std::env::var("NOMINA_4E_CAS_PROFILE").unwrap_or_else(|_|"unspecified-test-profile".into());assert!(["debug-default","test-crypto-opt","unspecified-test-profile"].contains(&profile.as_str()));let report=serde_json::json!({"profile":profile,"debugAssertions":cfg!(debug_assertions),"lockBudgetMs":5000,"mutexWaitMs":gate_wait_ms,"osLockWaitMs":os_lock_wait_ms,"uncontendedReplayMs":replay_ms,"exclusiveReplayGuardHoldMs":exclusive_replay_hold_ms,"observedBusyIntervalsMs":observed.lock().unwrap().clone(),"busyIntervalsScope":"External try_lock sampling at5ms; adjacent holders may merge; not exact per-writer instrumentation","actualSeparateProcesses":true,"results":results,"timeoutsOrCasChanged":false,"performanceIssueResolved":false,"source":"Authentic fiscal-only 4-B legacy copy; no salary seeding"});fs::write(Path::new(env!("CARGO_MANIFEST_DIR")).join(format!("../docs/evidence/5d3b4e/cas-{profile}.json")),serde_json::to_vec_pretty(&report).unwrap()).unwrap();fs::remove_dir_all(root).unwrap();
}
#[test]#[ignore="Actual CAS diagnostic subprocess; invoked by assessment parent"]fn cas_child(){let root=PathBuf::from(std::env::var_os("NOMINA_4E_CAS_ROOT").unwrap());assert!(root.starts_with(std::env::temp_dir().join("opencode")));assert!(root.file_name().unwrap().to_string_lossy().starts_with("5d3b4e-cas-"));let repo=repository(root.clone());let action:Action=core::decode_closed(&core::strict_json::parse(&fs::read(root.join("selection-request.json")).unwrap()).unwrap()).unwrap();let started=Instant::now();let outcome=match repo.mutate(&id(),6,move |_|Ok((action,BTreeMap::new()))){Ok(_)=>"SELECTED",Err(e)if e.code=="STALE_GENERATION"=>"STALE_GENERATION",Err(e)if e.code=="BUSY"=>"BUSY",Err(e)=>panic!("{e:?}")};println!("CAS_4E_OBSERVATION:{}",serde_json::json!({"outcome":outcome,"totalMutationMs":started.elapsed().as_secs_f64()*1000.,"processId":std::process::id()}));std::io::stdout().flush().unwrap();}
